package com.eventpulse.handler;
import com.amazonaws.services.lambda.runtime.Context;import com.eventpulse.dto.*;import com.eventpulse.model.*;import com.eventpulse.service.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class HandlerTests {
 @Test void eventHandlerListsPublicEvents(){var events=mock(EventService.class);when(events.list()).thenReturn(List.of());var handler=new EventHandler(events,mock(RegistrationService.class));var response=handler.handleRequest(HandlerTestSupport.event(HandlerTestSupport.request("GET","/events","")),mock(Context.class));assertEquals(200,response.getStatusCode());}
 @Test void eventHandlerRejectsMalformedJsonAndNonAdmin(){var events=mock(EventService.class);var handler=new EventHandler(events,mock(RegistrationService.class));String base=HandlerTestSupport.request("POST","/events",HandlerTestSupport.claims("u","USER"));String malformed=base.substring(0,base.length()-1).replace("\"body\":null","\"body\":\"{broken\"")+"}";var response=handler.handleRequest(HandlerTestSupport.event(malformed),mock(Context.class));assertEquals(403,response.getStatusCode());assertTrue(response.getBody().contains("ACCESS_DENIED"));}
 @Test void eventHandlerRejectsMalformedJsonForAdmin(){var handler=new EventHandler(mock(EventService.class),mock(RegistrationService.class));String request=HandlerTestSupport.request("POST","/events",HandlerTestSupport.claims("a","ADMIN"));String malformed=request.replace("\"body\":null","\"body\":\"{broken\"");assertEquals(400,handler.handleRequest(HandlerTestSupport.event(malformed),mock(Context.class)).getStatusCode());}
 @Test void eventHandlerRequiresClaimsForRegistration(){var handler=new EventHandler(mock(EventService.class),mock(RegistrationService.class));String json=HandlerTestSupport.request("POST","/events/e/registrations","").replace("\"body\":null","\"pathParameters\":{\"eventId\":\"e\"},\"body\":null");var response=handler.handleRequest(HandlerTestSupport.event(json),mock(Context.class));assertEquals(401,response.getStatusCode());}
 @Test void adminCanAnnounceToCurrentRegistrants(){var events=mock(EventService.class);var event=new Event();event.setEventId("e");when(events.get("e")).thenReturn(event);var lifecycle=mock(EventLifecycleService.class);when(lifecycle.announce(event)).thenReturn(List.of());var handler=new EventHandler(events,mock(RegistrationService.class),lifecycle);String json=HandlerTestSupport.request("POST","/events/e/announcements",HandlerTestSupport.claims("admin","ADMIN")).replace("\"body\":null","\"pathParameters\":{\"eventId\":\"e\"},\"body\":null");var response=handler.handleRequest(HandlerTestSupport.event(json),mock(Context.class));assertEquals(200,response.getStatusCode());verify(lifecycle).announce(event);}
 @Test void adminDashboardReturnsDashboardSummary(){var summary=mock(DashboardService.class);var expected=Map.<String,Object>of("totalEvents",2,"upcomingEvents",1,"completedEvents",1,"cancelledEvents",0,"registrationCounts",Map.of("e1",3,"e2",0));when(summary.summary()).thenReturn(expected);var handler=new EventHandler(mock(EventService.class),mock(RegistrationService.class),null,null,summary);var response=handler.handleRequest(HandlerTestSupport.event(HandlerTestSupport.request("GET","/admin/dashboard",HandlerTestSupport.claims("admin","ADMIN"))),mock(Context.class));assertEquals(200,response.getStatusCode());try{assertEquals(expected,com.eventpulse.util.ResponseUtil.JSON.readValue(response.getBody(),Map.class));}catch(Exception e){fail(e);}verify(summary).summary();}
 @Test void adminDashboardRejectsUserWithForbiddenResponse(){var summary=mock(DashboardService.class);var handler=new EventHandler(mock(EventService.class),mock(RegistrationService.class),null,null,summary);var response=handler.handleRequest(HandlerTestSupport.event(HandlerTestSupport.request("GET","/admin/dashboard",HandlerTestSupport.claims("user","USER"))),mock(Context.class));assertEquals(403,response.getStatusCode());assertTrue(response.getBody().contains("ACCESS_DENIED"));verifyNoInteractions(summary);}
 @Test void adminDashboardRejectsMissingAuthorizerClaimsAsUnauthenticated(){var handler=new EventHandler(mock(EventService.class),mock(RegistrationService.class),null,null,mock(DashboardService.class));var response=handler.handleRequest(HandlerTestSupport.event(HandlerTestSupport.request("GET","/admin/dashboard","")),mock(Context.class));assertEquals(401,response.getStatusCode());assertTrue(response.getBody().contains("ACCESS_DENIED"));}
 @Test void adminDashboardRejectsClaimsWithoutSubjectEvenWhenGroupIsAdmin(){String claims=",\"authorizer\":{\"jwt\":{\"claims\":{\"cognito:groups\":\"[ADMIN]\"}}}}";var handler=new EventHandler(mock(EventService.class),mock(RegistrationService.class),null,null,mock(DashboardService.class));var response=handler.handleRequest(HandlerTestSupport.event(HandlerTestSupport.request("GET","/admin/dashboard",claims)),mock(Context.class));assertEquals(401,response.getStatusCode());}
 @Test void adminDashboardMapsServiceFailuresToInternalError(){var summary=mock(DashboardService.class);when(summary.summary()).thenThrow(new IllegalStateException("database unavailable"));var handler=new EventHandler(mock(EventService.class),mock(RegistrationService.class),null,null,summary);var response=handler.handleRequest(HandlerTestSupport.event(HandlerTestSupport.request("GET","/admin/dashboard",HandlerTestSupport.claims("admin","ADMIN"))),mock(Context.class));assertEquals(500,response.getStatusCode());assertTrue(response.getBody().contains("INTERNAL_ERROR"));assertFalse(response.getBody().contains("database unavailable"));}
 @Test void registrationHandlerReturnsNotFoundWhenPathParameterMissing(){var handler=new RegistrationHandler(mock(RegistrationService.class));var response=handler.handleRequest(HandlerTestSupport.event(HandlerTestSupport.request("DELETE","/registrations/","")),mock(Context.class));assertEquals(404,response.getStatusCode());}
 @Test void registrationHandlerCancelsForAuthenticatedOwner(){var service=mock(RegistrationService.class);var registration=new Registration();registration.setRegistrationId("r");when(service.cancel("r","u")).thenReturn(registration);var handler=new RegistrationHandler(service);String request=HandlerTestSupport.request("DELETE","/registrations/r",HandlerTestSupport.claims("u","USER")).replace("\"body\":null","\"pathParameters\":{\"registrationId\":\"r\"},\"body\":null");var response=handler.handleRequest(HandlerTestSupport.event(request),mock(Context.class));assertEquals(200,response.getStatusCode());verify(service).cancel("r","u");}
 @Test void userHandlerUsesCognitoGetUserForVerifiedProfileEmail(){var users=mock(UserService.class);var cognito=mock(CognitoProfileService.class);var handler=new UserHandler(users,mock(RegistrationService.class),cognito);UserProfile profile=new UserProfile();profile.setUserId("u");when(cognito.getCurrentUser("signed-token","u")).thenReturn(new CognitoProfileService.ProfileAttributes("verified@example.test","Test User"));when(users.get("u","verified@example.test","Test User",false)).thenReturn(profile);String request=HandlerTestSupport.withBearer(HandlerTestSupport.request("GET","/users/me",HandlerTestSupport.claims("u","USER")),"signed-token");var response=handler.handleRequest(HandlerTestSupport.event(request),mock(Context.class));assertEquals(200,response.getStatusCode());verify(users).get("u","verified@example.test","Test User",false);verify(cognito).getCurrentUser("signed-token","u");}
 @Test void eventRegistrationSynchronizesProfileFromCognitoBeforeCreatingRegistration(){var events=mock(EventService.class);var registrations=mock(RegistrationService.class);var users=mock(UserService.class);var cognito=mock(CognitoProfileService.class);var registration=new Registration();registration.setRegistrationId("r");when(cognito.getCurrentUser("signed-token","u")).thenReturn(new CognitoProfileService.ProfileAttributes("verified@example.test","Test User"));when(registrations.register("e","u")).thenReturn(registration);var handler=new EventHandler(events,registrations,null,users,null,cognito);String request=HandlerTestSupport.request("POST","/events/e/registrations",HandlerTestSupport.claims("u","USER")).replace("\"body\":null","\"pathParameters\":{\"eventId\":\"e\"},\"body\":null");request=HandlerTestSupport.withBearer(request,"signed-token");var response=handler.handleRequest(HandlerTestSupport.event(request),mock(Context.class));assertEquals(201,response.getStatusCode());verify(users).get("u","verified@example.test","Test User",false);verify(registrations).register("e","u");}
 @Test void notificationHandlerUsesAuthenticatedSubject(){var service=mock(NotificationService.class);when(service.history("u",20)).thenReturn(List.of());var handler=new NotificationHandler(service);var response=handler.handleRequest(HandlerTestSupport.event(HandlerTestSupport.request("GET","/users/me/notifications",HandlerTestSupport.claims("u","USER"))),mock(Context.class));assertEquals(200,response.getStatusCode());verify(service).history("u",20);}
 @Test void reminderHandlerValidatesInputAndDelegates(){var service=mock(ReminderService.class);when(service.sendReminder("event","1h")).thenReturn(2);var handler=new ReminderHandler(service);assertThrows(IllegalArgumentException.class,()->handler.handleRequest(Map.of(),mock(Context.class)));assertTrue(handler.handleRequest(Map.of("eventId","event","reminderType","1h"),mock(Context.class)).contains("2 recipients"));}
}
